def _strategy_cost_scenarios(value: Any) -> list[dict[str, Any]]:
    if value is None:
        return [{"scenario_id": "source_config", "overrides": {}}]
    if not isinstance(value, list) or not 1 <= len(value) <= 3:
        raise HTTPException(status_code=422, detail="cost_scenarios must contain 1 to 3 entries")
    scenarios: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item in value:
        if not isinstance(item, dict) or set(item) != {"scenario_id", "overrides"}:
            raise HTTPException(status_code=422, detail="cost scenario fields do not match the contract")
        scenario_id = item["scenario_id"]
        overrides = item["overrides"]
        if not isinstance(scenario_id, str):
            raise HTTPException(status_code=422, detail="scenario_id is invalid")
        if scenario_id != "source_config" and not _COST_SCENARIO_ID_RE.fullmatch(scenario_id):
            raise HTTPException(status_code=422, detail="scenario_id must use lowercase letters, digits, _ or -")
        if scenario_id in seen:
            raise HTTPException(status_code=422, detail="scenario_id values must be unique")
        seen.add(scenario_id)
        if not isinstance(overrides, dict):
            raise HTTPException(status_code=422, detail="scenario overrides must be an object")
        if scenario_id == "source_config" and overrides:
            raise HTTPException(status_code=422, detail="source_config overrides must be empty")
        if scenario_id != "source_config" and not overrides:
            raise HTTPException(status_code=422, detail="stress scenarios require at least one cost override")
        clean_overrides: dict[str, int | float] = {}
        for key, number in overrides.items():
            maximum = _STRATEGY_COST_LIMITS.get(key)
            if maximum is None:
                raise HTTPException(status_code=422, detail=f"unsupported native cost field: {key}")
            if isinstance(number, bool) or not isinstance(number, (int, float)):
                raise HTTPException(status_code=422, detail=f"{key} must be a JSON number")
            if not math.isfinite(float(number)) or number < 0 or number > maximum:
                raise HTTPException(status_code=422, detail=f"{key} must be finite and in [0, {maximum}]")
            clean_overrides[key] = number
        scenarios.append({"scenario_id": scenario_id, "overrides": clean_overrides})
    if "source_config" not in seen:
        raise HTTPException(status_code=422, detail="cost_scenarios require one source_config entry")
    return scenarios


