def _remove_versioned_run(run_id: str, run_dir: Path) -> None:
    try:
        private_root = get_runs_dir().resolve(strict=True)
        candidate = run_dir.resolve(strict=True)
        if candidate.parent == private_root and candidate.name == run_id:
            shutil.rmtree(candidate, ignore_errors=True)
    except OSError:
        return


def _run_code_sha256(run_dir: Path) -> str:
    code_dir = run_dir / "code"
    if _is_link(code_dir) or not code_dir.is_dir():
        raise HTTPException(status_code=422, detail="input run code directory is unavailable")
    digest = hashlib.sha256()
    total_size = 0
    has_signal_engine = False
    for path in sorted(code_dir.rglob("*")):
        relative = path.relative_to(code_dir)
        if any(part.lower() in {"__pycache__", ".cache", "cache"} for part in relative.parts):
            continue
        if _is_link(path):
            raise HTTPException(status_code=422, detail="input code may not contain symlinks or junctions")
        if path.suffix.lower() in {".pyc", ".pyo"}:
            continue
        resolved = path.resolve(strict=True)
        if not resolved.is_relative_to(run_dir.resolve(strict=True)) or not resolved.is_relative_to(code_dir.resolve(strict=True)):
            raise HTTPException(status_code=422, detail="input code escapes the private run directory")
        if path.is_dir():
            continue
        if not path.is_file():
            raise HTTPException(status_code=422, detail="input code contains an unsupported filesystem entry")
        name = path.name.lower()
        if (
            name == ".env"
            or name.startswith((".env.", "credentials", "secrets"))
            or path.suffix.lower() in {".pem", ".key", ".p12", ".pfx"}
        ):
            raise HTTPException(status_code=422, detail="input code must not contain credential files")
        total_size += path.stat().st_size
        if total_size > _BACKTEST_INPUT_LIMIT:
            raise HTTPException(status_code=413, detail="input code exceeds 16 MiB")
        content = _read_bounded(path, _BACKTEST_INPUT_LIMIT, "input code file")
        digest.update(relative.as_posix().encode("utf-8"))
        digest.update(b"\0")
        digest.update(content)
        digest.update(b"\0")
        has_signal_engine = has_signal_engine or relative.as_posix() == "signal_engine.py"
    if not has_signal_engine:
        raise HTTPException(status_code=422, detail="input code/signal_engine.py is required")
    return digest.hexdigest()


def _strategy_source_context(run_dir: Path) -> dict[str, Any]:
    config_path = run_dir / "config.json"
    if _is_link(config_path) or not config_path.is_file():
        raise HTTPException(status_code=422, detail="input run config.json is unavailable")
    config_bytes = _read_bounded(config_path, 1024 * 1024, "input config")
    try:
        config = json.loads(config_bytes)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise HTTPException(status_code=422, detail="input config.json is invalid") from exc
    if not isinstance(config, dict) or _contains_credentials(config):
        raise HTTPException(status_code=422, detail="input config must be an object without credentials")

    code_sha256 = _run_code_sha256(run_dir)
    codes = config.get("codes")
    reason_code: str | None = None
    development_window: list[str] | None = None
    if not isinstance(codes, list) or not codes or any(not isinstance(code, str) for code in codes):
        reason_code = "a_share_codes_required"
    else:
        from backtest.engines._market_hooks import _detect_market

        if any(_detect_market(code) != "a_share" for code in codes):
            reason_code = "a_share_codes_required"

    start = config.get("start_date")
    end = config.get("end_date")
    try:
        if not isinstance(start, str) or not isinstance(end, str):
            raise ValueError("development window is absent")
        _valid_iso_date(start, "source start_date")
        _valid_iso_date(end, "source end_date")
        if start > end:
            raise ValueError("development window is invalid")
        development_window = [start, end]
    except (HTTPException, ValueError):
        reason_code = reason_code or "development_window_unavailable"

    state_path = run_dir / "state.json"
    artifacts_dir = run_dir / "artifacts"
    equity_path = artifacts_dir / "equity.csv"
    metrics_path = artifacts_dir / "metrics.csv"
    for path in (state_path, artifacts_dir, equity_path, metrics_path):
        if _is_link(path):
            raise HTTPException(status_code=422, detail="source run artifacts may not contain links")
    state_status = None
    if state_path.is_file():
        try:
            state = json.loads(_read_bounded(state_path, 64 * 1024, "source run state"))
            if isinstance(state, dict):
                state_status = state.get("status")
        except (UnicodeDecodeError, json.JSONDecodeError, HTTPException):
            state_status = None
    artifacts_complete = equity_path.is_file() and metrics_path.is_file()
    completed = artifacts_complete and (state_status is None or state_status in {"success", "completed"})
    if not completed:
        reason_code = reason_code or "source_run_not_completed"
    if reason_code is None and _resolved_a_share_costs(config) is None:
        reason_code = "source_cost_config_invalid"

    return {
        "config": config,
        "config_sha256": hashlib.sha256(config_bytes).hexdigest(),
        "code_sha256": code_sha256,
        "development_window": development_window,
        "reason_code": reason_code,
    }


def _default_strategy_validation() -> dict[str, dict[str, Any]]:
    """Use bounded defaults from the native validation module, not new math."""
    return {
        "monte_carlo": {"n_simulations": 1000, "seed": 42},
        "bootstrap": {"n_bootstrap": 1000, "confidence": 0.95, "seed": 42},
        "walk_forward": {"n_windows": 5},
    }


def _resolved_a_share_costs(config: dict[str, Any]) -> dict[str, float] | None:
    from backtest.engines.china_a import ChinaAEngine

    try:
        engine = ChinaAEngine(config)
        values = {
            "commission_rate": engine.commission_rate,
            "commission_min": engine.commission_min,
            "stamp_tax": engine.stamp_tax,
            "transfer_fee": engine.transfer_fee,
            "slippage": engine.slippage_rate,
        }
    except Exception:
        return None
    if any(
        isinstance(value, bool)
        or not isinstance(value, (int, float))
        or not math.isfinite(float(value))
        or not 0 <= value <= _STRATEGY_COST_LIMITS[key]
        for key, value in values.items()
    ):
        return None
    return {key: float(value) for key, value in values.items()}


