def _validation_check_payload(raw: Any) -> dict[str, Any]:
    if not isinstance(raw, dict):
        return {"status": "failed", "result": None}
    if "error" in raw:
        return {"status": "not_applicable", "result": raw}
    return {"status": "completed", "result": raw}


def _read_strategy_validation(run_dir: Path) -> dict[str, Any]:
    validation_path = run_dir / "artifacts" / "validation.json"
    if _is_link(validation_path) or not validation_path.is_file():
        return {
            "status": "not_run",
            "outcome": "unavailable",
            "outcome_reason_code": "native_validation_artifact_missing",
            "checks": None,
            "artifact_available": False,
        }
    try:
        raw = json.loads(_read_bounded(validation_path, 1024 * 1024, "validation artifact"))
    except (HTTPException, UnicodeDecodeError, json.JSONDecodeError):
        return {
            "status": "failed",
            "outcome": "unavailable",
            "outcome_reason_code": "native_validation_artifact_invalid",
            "checks": None,
            "artifact_available": False,
        }
    if not isinstance(raw, dict):
        return {
            "status": "failed",
            "outcome": "unavailable",
            "outcome_reason_code": "native_validation_artifact_invalid",
            "checks": None,
            "artifact_available": False,
        }
    checks = {
        name: _validation_check_payload(raw[name]) if name in raw else {"status": "not_run", "result": None}
        for name in ("monte_carlo", "bootstrap", "walk_forward")
    }
    statuses = [check["status"] for check in checks.values()]
    completed = sum(status == "completed" for status in statuses)
    if "failed" in statuses:
        status = "failed"
    elif completed == len(statuses):
        status = "completed"
    elif completed:
        status = "partial"
    elif "not_applicable" in statuses:
        status = "not_applicable"
    else:
        status = "not_run"
    return {
        "status": status,
        "outcome": "unavailable",
        "outcome_reason_code": "no_native_aggregate_gate",
        "checks": checks,
        "artifact_available": True,
    }


def _strategy_metrics(run_dir: Path) -> dict[str, Any] | None:
    card_path = run_dir / "run_card.json"
    equity_path = run_dir / "artifacts" / "equity.csv"
    if _is_link(card_path) or _is_link(equity_path) or not card_path.is_file() or not equity_path.is_file():
        return None
    try:
        card = json.loads(_read_bounded(card_path, 1024 * 1024, "run card"))
        equity_rows = _equity_row_count(equity_path)
    except (HTTPException, OSError, UnicodeDecodeError, json.JSONDecodeError, ValueError):
        return None
    metrics = card.get("metrics") if isinstance(card, dict) else None
    if not isinstance(metrics, dict) or equity_rows < 2:
        return None
    total_return = metrics.get("total_return")
    if isinstance(total_return, bool) or not isinstance(total_return, (int, float)) or not math.isfinite(float(total_return)):
        return None
    keys = ("total_return", "max_drawdown", "trade_count", "sharpe", "annual_return", "final_value", "calmar", "win_rate")
    clean: dict[str, Any] = {}
    for key in keys:
        value = metrics.get(key)
        if isinstance(value, bool):
            continue
        if isinstance(value, (int, float)) and math.isfinite(float(value)):
            clean[key] = value
    return clean if "total_return" in clean else None


def _equity_row_count(path: Path) -> int:
    import csv

    with path.open("r", encoding="utf-8-sig", newline="") as stream:
        rows = csv.reader(stream)
        next(rows, None)
        return sum(1 for _ in rows)


def _run_strategy_oos_validation(
    payload: dict[str, Any],
    on_run_created: Any = None,
) -> tuple[str, dict[str, Any]]:
    input_run_id = payload["input_run_id"]
    context = payload["_source_context"]
    references: dict[str, Any] = {
        "input_run_id": input_run_id,
        "code_sha256": context["code_sha256"],
        "run_ids": [],
        "scenario_ids": [scenario["scenario_id"] for scenario in payload["cost_scenarios"]],
    }
    reason_code = context.get("reason_code")
    if reason_code:
        return json.dumps(_strategy_validation_not_applicable(payload, reason_code), ensure_ascii=False, allow_nan=False), references

    results: list[dict[str, Any]] = []
    successful = 0
    for scenario in payload["cost_scenarios"]:
        run_id: str | None = None
        run_dir: Path | None = None
        scenario_result: dict[str, Any] = {
            "scenario_id": scenario["scenario_id"],
            "status": "failed",
            "run_id": None,
            "code_sha256": None,
            "effective_cost_config": None,
            "backtest_summary": None,
            "validation": {
                "status": "not_run",
                "outcome": "unavailable",
                "outcome_reason_code": "backtest_not_completed",
                "checks": None,
                "artifact_available": False,
            },
        }
        try:
            run_id, run_dir = _copy_versioned_run(input_run_id, Path(payload["_input_run_dir"]))
            config_path = run_dir / "config.json"
            copied_config_bytes = _read_bounded(config_path, 1024 * 1024, "copied config")
            if hashlib.sha256(copied_config_bytes).hexdigest() != context["config_sha256"]:
                raise RuntimeError("input config changed before the experiment copy")
            if _run_code_sha256(run_dir) != context["code_sha256"]:
                raise RuntimeError("input strategy code changed before the experiment copy")
            config = json.loads(copied_config_bytes)
            if not isinstance(config, dict):
                raise RuntimeError("copied config is invalid")
            config["start_date"] = payload["window_start"]
            config["end_date"] = payload["window_end"]
            config["validation"] = _default_strategy_validation()
            config.update(scenario["overrides"])
            effective_costs = _resolved_a_share_costs(config)
            if effective_costs is None:
                raise RuntimeError("effective native cost configuration is invalid")
            config_path.write_text(json.dumps(config, ensure_ascii=False, indent=2, allow_nan=False) + "\n", encoding="utf-8")
            scenario_result["run_id"] = run_id
            scenario_result["code_sha256"] = context["code_sha256"]
            scenario_result["effective_cost_config"] = effective_costs
            references["run_ids"].append(run_id)
            if on_run_created is not None:
                on_run_created(list(references["run_ids"]))

            from src.tools.backtest_tool import BacktestTool

            raw = BacktestTool().execute(run_dir=str(run_dir))
            try:
                backtest_result = json.loads(raw)
            except json.JSONDecodeError:
                backtest_result = None
            metrics = _strategy_metrics(run_dir) if isinstance(backtest_result, dict) and backtest_result.get("status") == "ok" else None
            if metrics is None:
                scenario_result["status"] = "failed"
                scenario_result["reason_code"] = "no_usable_backtest_metrics"
                scenario_result["validation"]["outcome_reason_code"] = "backtest_has_no_usable_metrics"
                results.append(scenario_result)
                continue

            scenario_result["status"] = "completed"
            scenario_result["backtest_summary"] = {"metrics": metrics}
            scenario_result["validation"] = _read_strategy_validation(run_dir)
            successful += 1
        except Exception:
            if run_id is not None and run_id not in references["run_ids"] and run_dir is not None:
                _remove_versioned_run(run_id, run_dir)
            scenario_result["status"] = "failed"
            scenario_result["reason_code"] = "native_backtest_failed" if run_dir is not None else "experiment_run_creation_failed"
            scenario_result["validation"]["outcome_reason_code"] = scenario_result["reason_code"]
        results.append(scenario_result)

    if successful == len(results):
        experiment_status = "completed"
        operation_status = "ok"
    elif successful:
        experiment_status = "partial"
        operation_status = "ok"
    else:
        experiment_status = "failed"
        operation_status = "error"
    result = {
        "status": operation_status,
        "experiment_status": experiment_status,
        "input_run_id": input_run_id,
        "development_window": context["development_window"],
        "test_window": [payload["window_start"], payload["window_end"]],
        "code_sha256": context["code_sha256"],
        "scenarios": results,
        "strict_factor_validation": {
            "status": "not_applicable",
            "executed": False,
            "reason_code": "cross_sectional_factor_inputs_required",
        },
    }
    if experiment_status == "failed":
        result["reason_code"] = "all_scenarios_failed"
    return json.dumps(result, ensure_ascii=False, allow_nan=False), references


